"""Merge agent-researched company data into ats_api.py"""
import re

from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
PROJECT_ROOT = BASE_DIR.parent
API_PATH = PROJECT_ROOT / "vellum-os" / "vellum" / "tools" / "ats_client.py"

def read_company_file(filename: str) -> str:
    path = BASE_DIR / filename
    if path.exists():
        return path.read_text(encoding="utf-8").strip()
    return ""

content = ""
if API_PATH.exists():
    with open(API_PATH, "r", encoding="utf-8") as f:
        content = f.read()

# Helper to parse comma-separated lists
def parse_csv(text):
    items = []
    for part in text.replace("\n", " ").split(","):
        part = part.strip().strip('"').strip("'").strip()
        if part and not part.startswith("#"):
            items.append(part)
    return items

def dedup(items):
    seen = set()
    result = []
    for item in items:
        slug = item.lower().replace(" ", "-").replace("'", "").replace("&", "and")
        slug = re.sub(r"[^a-zA-Z0-9\-]", "", slug)
        if slug and slug not in seen:
            seen.add(slug)
            result.append(slug)
    return result

def format_company_list(companies, indent=8):
    """Format a list of company slugs into Python code lines."""
    companies = dedup(companies)
    companies.sort()
    prefix = " " * indent
    lines = []
    i = 0
    while i < len(companies):
        chunk = companies[i:i+8]
        lines.append(prefix + ", ".join(f'"{c}"' for c in chunk) + ",")
        i += 8
    return "\n".join(lines)

def replace_city_section(content, city_key, new_companies):
    """Replace a city's company list in the TECH_HUB_STARTUPS dict."""
    pattern = rf'(    "{re.escape(city_key)}": \[\n).*?(\n    \],)'
    formatted = format_company_list(new_companies)
    replacement = f'    "{city_key}": [\n{formatted}\n    ],'
    if not re.search(pattern, content, re.DOTALL):
        print(f"WARNING: Could not find city '{city_key}' in file!")
        return content
    return re.sub(pattern, replacement, content, count=1, flags=re.DOTALL)

